	if err := json.Unmarshal([]byte(annotation), &entries); err != nil {
		return nil, fmt.Errorf("parse Multus annotation on %s: %w", pod.Name, err)
	}

	for _, entry := range entries {
		if entry.Name == backupNetworkName || entry.Interface == "net1" {
